import { Component, For, onCleanup, onMount, useContext } from "solid-js";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import ActionHandler from "#core/ui/input/action-handler.js";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { VSlot } from "#core/ui-next/components/slot.jsx";
import { HotkeyContext } from "#core/ui-next/services/hotkey.js";
import { LayoutModel } from "#core/ui-next/utilities/layout-utilities.js";

import { VictoriesAltBase } from "#base/ui-next/screens/victories/victories-alt-base.js";
import { useVictoriesScreenContext, VictoryTabType } from "#base/ui-next/screens/victories/victories-screen-model.js";
import { VictoryRow } from "#base/ui-next/screens/victories/victory-tab-base.jsx";

const audio = useAudio("VictoryScreen/TabListItem")

export const ScoreVictoryTab: Component = () => {
	const model = useVictoriesScreenContext();
	const layoutModel = LayoutModel.get();
	const hotkeyContext = useContext(HotkeyContext);

	onMount(() => {
		model.tabNavStartup(hotkeyContext);
		audio("tab-nav-score")
	});

	onCleanup(() => {
		model.tabNavShutdown(hotkeyContext);
	});

	return (
		<VictoriesAltBase
			isScoreTab={true}
			backgroundImage="url(bg-panel-iceland)"
			backgroundClass="absolute top-4 bottom-0 left-0 right-0 relative bg-cover bg-no-repeat opacity-20 pointer-events-none"
			headerText={model.data.scoreDetails.headerText}
			victoryName="LOC_VICTORY_SCORE_NAME"
			titleColorClass="victories-color-score"
			scrollAreaClass={() =>
				`victories-scroll-base ${layoutModel.screenHeightDownScaled() < 1000 ? "w-full" : "victories-econ-cols-1-and-2-and-4"}`
			}
			headerContent={() => (
				<div class="w-full h-full flex flex-row">
					<div class="w-full self-center">
						<div class="ml-2 uppercase fxs-header">
							<L10n.Compose text="LOC_VICTORY_SCORE_CONTRIBUTORS" />
						</div>
					</div>
				</div>
			)}
			rightContent={() => (
				<div class={`victories-econ-col-3 victories-economic-graph relative`}>
					<div class="ml-8 mt-8 font-title-lg">
						<div class="fxs-header uppercase">
							<L10n.Stylize text="LOC_VICTORIES_RULES_SCORE_HEADER_1" />
						</div>
						<div class="font-body-base text-body">
							<L10n.Stylize text="LOC_VICTORIES_RULES_SCORE_BODY_1" />
						</div>
						<div class="fxs-header mt-4 uppercase">
							<L10n.Stylize text="LOC_VICTORIES_RULES_SCORE_HEADER_2" />
						</div>
						<div class="font-body-base text-body">
							<L10n.Stylize text="LOC_VICTORIES_RULES_SCORE_BODY_2" />
						</div>
					</div>
				</div>
			)}
			rightContentSmallScreen={() => (
				<>
					<div class="victories-econ-col-1-and-2-and-4 h-full relative" />
					<div class="victories-econ-col-3 victories-economic-graph relative">
						<div class="ml-8 mt-8 font-title-lg">
							<div class="fxs-header uppercase">
								<L10n.Stylize text="LOC_VICTORIES_RULES_SCORE_HEADER_1" />
							</div>
							<div class="font-body-base text-body">
								<L10n.Stylize text="LOC_VICTORIES_RULES_SCORE_BODY_1" />
							</div>
							<div class="fxs-header mt-4 uppercase">
								<L10n.Stylize text="LOC_VICTORIES_RULES_SCORE_HEADER_2" />
							</div>
							<div class="font-body-base text-body">
								<L10n.Stylize text="LOC_VICTORIES_RULES_SCORE_BODY_2" />
							</div>
						</div>
					</div>
				</>
			)}
		>
			<VSlot
				class="relative pointer-events-auto victories-economic-focus transition-opacity duration-150 ease-out flex flex-col victories-econ-col-1-and-2-and-4"
				lockNavigation={true}
				autoFocus={!model.tooltipToggle}
			>
				<For each={model.data.scoreDetails.playerDetails}>
					{(player, index) => (
						<VictoryRow
							rowId={index() + 1}
							playerInfo={player.playerInfo}
							divider={false}
							rowType={VictoryTabType.Score}
							skipContentColumn={true}
							columnClassOverride="econ"
							omitBottomLine={true}
							activateInfo={(playerId: PlayerId) => {
								if (ActionHandler.isTouchActive) {
									model.focusPlayer(playerId, VictoryTabType.Score);
									model.onGamepadInspectButton();
								}
							}}
						/>
					)}
				</For>
			</VSlot>
		</VictoriesAltBase>
	);
};
